(() => {
  'use strict';
  const M=window.PeregriniEditorModel,client=window.PeregriniEditorGitHub.createClient();
  const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let data=null,base=null,workIndex=0,formatIndex=0,dirty=false,busy=false;
  const work=()=>data?.works[workIndex],version=()=>work()?.variants[formatIndex];
  function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
  function status(){ $('dirty-state').textContent=dirty?'Alterações ainda não enviadas':'Sem alterações pendentes';$('save').disabled=!dirty||busy; }
  function mark(){dirty=true;$('publication').hidden=true;status();}
  function lock(value){busy=value;$('fields').disabled=value;['save','download','reload','preview','new-work','disconnect'].forEach(id=>$(id).disabled=value);$('work-list').querySelectorAll('button').forEach(b=>b.disabled=value);status();}
  function options(values,value){return Object.entries(values).map(([key,label])=>`<option value="${escape(key)}" ${value===key?'selected':''}>${escape(label)}</option>`).join('');}
  function list(){ $('work-list').replaceChildren();data.works.forEach((w,i)=>{const b=document.createElement('button');b.type='button';b.textContent=w.title||'Sem título';if(i===workIndex)b.setAttribute('aria-current','true');b.onclick=()=>{workIndex=i;formatIndex=0;render();};$('work-list').append(b);}); }
  function field(id,obj,key,parser=x=>x,event='input'){ $(id).addEventListener(event,()=>{obj[key]=parser($(id).value);mark();if(key==='title'&&obj===work())list();}); }
  function render(){list();const w=work();if(!w){$('editor').innerHTML='<h2>Seu acervo está vazio</h2><p>Use “Nova obra” para começar.</p>';return;}const v=version();
    $('editor').innerHTML=`<h2>Editar obra</h2><label for="work-title">Título</label><input id="work-title" value="${escape(w.title)}"><p class="help">O endereço da obra é preservado quando você muda o título.</p><label for="work-kind">Tipo</label><input id="work-kind" list="kinds" value="${escape(w.kind)}"><datalist id="kinds"><option value="Ensaio"><option value="Suma"><option value="Reflexão"><option value="Teoria social"></datalist><label for="work-summary">Resumo</label><textarea id="work-summary" rows="3">${escape(w.summary)}</textarea><div class="variant-row"><label for="work-variant">Forma de apresentação<select id="work-variant">${w.variants.map((a,i)=>`<option value="${i}" ${i===formatIndex?'selected':''}>${a.id==='didatico'?'Didático':'Sintético'}</option>`).join('')}</select></label>${w.variants.length<2?'<button id="add-version" type="button">+ Outra apresentação</button>':''}</div><div class="row"><label for="version-status">Estado<select id="version-status">${options({andamento:'Em andamento',finalizado:'Finalizado'},v.status)}</select></label><label for="version-availability">Conteúdo disponível<select id="version-availability">${options({trecho:'Trecho',integral:'Texto integral',demonstracao:'Demonstração'},v.availability)}</select></label></div><div class="row" id="progress-fields" ${v.status==='finalizado'?'hidden':''}><label for="version-last">Última parte escrita<input id="version-last" value="${escape(v.last||'')}"></label><label for="version-next">Próxima parte<input id="version-next" value="${escape(v.next||'')}"></label></div><p class="help">A data de atualização é preenchida ao salvar. Separe os parágrafos por uma linha em branco.</p><div id="chapters"></div><button id="add-chapter" type="button">+ Adicionar capítulo</button><p><button id="delete-work" class="danger" type="button">Remover esta obra</button></p>`;
    field('work-title',w,'title');field('work-kind',w,'kind');field('work-summary',w,'summary');field('version-status',v,'status',x=>x,'change');field('version-availability',v,'availability',x=>x,'change');field('version-last',v,'last');field('version-next',v,'next');
    $('version-status').addEventListener('change',()=>{$('progress-fields').hidden=v.status==='finalizado';});
    $('work-variant').onchange=()=>{formatIndex=Number($('work-variant').value);render();};
    if($('add-version'))$('add-version').onclick=()=>{w.variants.push(M.variant(v.id==='didatico'?'sintetico':'didatico'));formatIndex=w.variants.length-1;mark();render();};
    v.chapters.forEach((c,i)=>renderChapter(c,i,v.chapters,$('chapters'),false));
    $('add-chapter').onclick=()=>{v.chapters.push(M.chapter(v));mark();render();$('chapters').lastElementChild?.scrollIntoView({block:'start'});};
    $('delete-work').onclick=()=>{if(!confirm(`Remover “${w.title}” do acervo? A remoção só será publicada ao salvar no GitHub.`))return;data.works.splice(workIndex,1);workIndex=Math.max(0,workIndex-1);formatIndex=0;mark();render();};
  }
  function renderChapter(c,i,siblings,parent,isSub){
    const box=document.createElement('section');box.className=isSub?'subchapter':'chapter-editor';
    const id=`edit-${c.id}`;
    box.innerHTML=`<div class="chapter-heading"><h3>${isSub?'Subcapítulo':'Capítulo'} ${i+1}</h3><div class="chapter-actions"><button type="button" data-action="up" ${i===0?'disabled':''} aria-label="Mover ${escape(c.title)} para cima">Subir</button><button type="button" data-action="down" ${i===siblings.length-1?'disabled':''} aria-label="Mover ${escape(c.title)} para baixo">Descer</button><button type="button" data-action="remove" class="danger">Remover</button></div></div><label for="${escape(id)}-title">Título ${isSub?'do subcapítulo':'do capítulo'}</label><input id="${escape(id)}-title" value="${escape(c.title)}"><label for="${escape(id)}-text">Texto</label><textarea class="paragraph-text" id="${escape(id)}-text" rows="9">${escape(c.paragraphs.join('\n\n'))}</textarea>`;
    parent.append(box);field(`${id}-title`,c,'title');field(`${id}-text`,c,'paragraphs',M.paragraphs);
    box.querySelector('[data-action="up"]').onclick=()=>{[siblings[i-1],siblings[i]]=[siblings[i],siblings[i-1]];mark();render();};
    box.querySelector('[data-action="down"]').onclick=()=>{[siblings[i+1],siblings[i]]=[siblings[i],siblings[i+1]];mark();render();};
    box.querySelector('[data-action="remove"]').onclick=()=>{if(!confirm(`Remover “${c.title}” e seu texto?`))return;siblings.splice(i,1);mark();render();};
    if(!isSub){(c.subchapters||[]).forEach((s,n)=>renderChapter(s,n,c.subchapters,box,true));const b=document.createElement('button');b.type='button';b.textContent='+ Adicionar subcapítulo';b.onclick=()=>{if(!c.subchapters)c.subchapters=[];c.subchapters.push(M.chapter(version(),'Novo subcapítulo'));mark();render();};box.append(b);}
  }
  function load(file){const parsed=M.validate(M.parse(file.text));data=parsed;base=M.clone(parsed);workIndex=0;formatIndex=0;dirty=false;$('workspace').hidden=false;$('connection').hidden=true;$('disconnect').hidden=false;$('publication').hidden=true;render();status();}
  $('connect-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;notice('Conectando à sua conta…');try{const file=await client.connect($('token').value);load(file);notice('Conectado. Escolha uma obra ou crie um novo texto.');}catch(e){client.disconnect();notice(e.message,true);}finally{$('token').value='';button.disabled=false;}};
  $('editor-form').onsubmit=e=>e.preventDefault();
  $('disconnect').onclick=()=>{if(dirty&&!confirm('Sair e descartar as alterações não enviadas? Você pode cancelar e baixar uma cópia primeiro.'))return;client.disconnect();data=base=null;dirty=false;$('editor').replaceChildren();$('work-list').replaceChildren();$('workspace').hidden=true;$('connection').hidden=false;$('disconnect').hidden=true;notice('Sessão encerrada.');};
  $('reload').onclick=async()=>{if(dirty&&!confirm('Recarregar e descartar as alterações não enviadas?'))return;lock(true);try{const file=await client.reload(text=>M.validate(M.parse(text)));load(file);notice('Acervo atualizado a partir do GitHub.');}catch(e){notice(e.message,true);}finally{lock(false);}};
  $('save').onclick=async()=>{if(!dirty||busy)return;const today=new Date(),date=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;let next;try{next=M.prepare(data,base,date);}catch(e){notice(e.message,true);return;}lock(true);notice('Salvando os textos no GitHub…');try{await client.save(JSON.stringify(next,null,2)+'\n');data=next;base=M.clone(next);dirty=false;$('publication').hidden=false;notice('Textos salvos no GitHub. Aguarde a publicação terminar para vê-los no site.');}catch(e){notice(e.message,true);}finally{lock(false);}};
  $('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='obras-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  $('new-work').onclick=()=>{$('new-title').value='';$('new-dialog').showModal();$('new-title').focus();};
  $('cancel-new').onclick=()=>$('new-dialog').close();
  $('new-form').onsubmit=e=>{e.preventDefault();const title=$('new-title').value.trim();if(!title)return;data.works.push(M.newWork(data,title));workIndex=data.works.length-1;formatIndex=0;mark();render();$('new-dialog').close();};
  $('preview').onclick=()=>{const w=work(),v=version();if(!w)return;const box=$('preview-content');box.replaceChildren();function add(tag,text,parent=box){const el=document.createElement(tag);el.textContent=text;parent.append(el);return el;}add('h1',w.title);add('p',data.author);add('p',w.summary);function sections(cs,level){for(const c of cs){add(`h${level}`,c.title);c.paragraphs.forEach(p=>add('p',p));sections(c.subchapters||[],level+1);}}sections(v.chapters,2);$('preview-dialog').showModal();};
  $('close-preview').onclick=()=>$('preview-dialog').close();
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
})();
